/**
 * Perform an action on multiple attachments (e.g. open or save)
 *
 * @param {AttachmentInfo[]} attachments - AttachmentInfo objects to work with.
 * @param {"open"|"save"|"saveAs"|"detach"|"delete"|"copyUrl"|"openFolder"} action - Action to take.
 */
function HandleMultipleAttachments(attachments, action) {
  // Feed message link attachments save handling.
  if (
    FeedUtils.isFeedMessage(gMessage) &&
    (action == "save" || action == "saveAs")
  ) {
    saveLinkAttachmentsToFile(attachments);
    return;
  }

  if (action != "copyUrl") {
    // Exclude attachments we can't act on: 1) deleted ones, or 2) detached ones
    // with missing external files.
    attachments = attachments.filter(attachment => attachment.hasFile);
  }
  attachments = attachments.filter(attachment => attachment.isAllowedURL);

  if (action == "detach" || action == "delete") {
    if (!CanDetachAttachments()) {
      return;
    }
    // Already detached attachments are not part of the message anymore.
    attachments = attachments.filter(
      attachment => !attachment.isExternalAttachment
    );
  }

  if (!attachments.length) {
    return;
  }

  switch (action) {
    case "save":
